  render: () => {
    const content = <div>\r
        <p>This is the content of the popover.</p>\r
        <p>It can contain multiple paragraphs.</p>\r
      </div>;
    return <Popover content={content} title="Popover Title">\r
        <Button>Hover me</Button>\r
      </Popover>;
  }
